import RNA
target="......((.......((.((.......((.((...............)).........((...............)).)).......)).((.......((...............)).......)).((.......((.((...............)).........((...............)).)).......)).((.......((...............)).......)).((.......((.((...............)).........((...............)).)).......)).((.......((...........((...............)).)).......)).)).......))......"
n=len(target)
stack=[]
pairs={}
order=[]
for i,c in enumerate(target):
    if c=='(':
        stack.append(i)
        order.append(('open',i))
    elif c==')':
        j=stack.pop()
        pairs[j]=i
        pairs[i]=j
        order.append(('close',i))
# For each pair, assign by nesting depth
# compute depth
depth={}
for i in range(n):
    if i in pairs:
        # depth = number of pairs enclosing it
        d=0
        for k in range(n):
            if k in pairs and k<i and pairs[k]>i:
                d+=1
        depth[i]=d
# Build: outer pairs (depth small) -> GC; inner pairs -> weaker AU
seq=['A']*n
for i in range(n):
    if i in pairs:
        j=pairs[i]
        if i<j:
            d=depth[i]
            if d<=1:
                a,b='G','C'
            else:
                a,b='G','C'  # keep GC for closing pairs
            seq[i]=a
            seq[j]=b
seq=''.join(seq)
fc=RNA.fold_compound(seq)
ss,mfe=fc.mfe()
print("match",ss==target, "dist", RNA.bp_distance(ss,target))
print("SEQ",seq)
