    if c=='(': stack.append(i)
    elif c==')':
        j=stack.pop(); pairs[j]=i; pairs[i]=j
# outermost pair spans 6..374 (the first ( at index 6 and last ) at 374)
# Find direct children: pairs (i,j) where no pair encloses them except outermost
top=[]
for i in range(n):
    if i in pairs and i<pairs[i]:
        j=pairs[i]
